            margin: 0;
            padding: 0;
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Futura', 'Helvetica Neue', Arial, sans-serif;
            background: linear-gradient(135deg, #000000 0%, #111111 100%);
            color: #FFFFFF;
            overflow-x: hidden;
        }
        .header {
            display: flex;
            align-items: center;
            padding: 20px 50px;
            background: rgba(0,0,0,0.9);
            position: fixed;
            width: 100%;
            top: 0;
            z-index: 1000;
            box-shadow: 0 2px 10px rgba(254,174,56,0.3);
        }
        .logo {
            width: 60px;
            height: 40px;
            fill: #FEAE38; /* NIKE orange */
        }
        .nike-text {
            font-size: 28px;
            font-weight: 900;
            letter-spacing: 2px;
            margin-left: 15px;
            color: #FFFFFF;
        }
        .hero {
            height: 100vh;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            background: url('https://via.placeholder.com/1920x1080/000000/FFFFFF?text=NIKE+HERO+IMAGE') center/cover;
            margin-top: 80px;
        }
        .swoosh-large {
            width: 300px;
            height: 100px;
            fill: #FEAE38;
            margin-bottom: 20px;
            animation: swooshFloat 3s ease-in-out infinite;
        }
        @keyframes swooshFloat {
            0%, 100% { transform: translateY(0px); }
            50% { transform: translateY(-10px); }
        }
        .just-do-it {
            font-size: 64px;
            font-weight: 900;
            letter-spacing: 4px;
            color: #FEAE38;
            text-transform: uppercase;
            margin: 0;
            text-shadow: 0 4px 20px rgba(254,174,56,0.5);
        }
        .tagline {
            font-size: 24px;
            margin-top: 10px;
            opacity: 0.9;
        }
        .products {
            padding: 100px 50px;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 40px;
            max-width: 1400px;
            margin: 0 auto;
        }
        .product-card {
            background: rgba(255,255,255,0.1);
            border-radius: 12px;
            padding: 30px;
            text-align: center;
            backdrop-filter: blur(10px);
            border: 1px solid rgba(254,174,56,0.2);
            transition: transform 0.3s ease;
        }
        .product-card:hover {
            transform: translateY(-10px);
        }
        .product-swoosh {
            width: 80px;
            height: 50px;
            fill: #FFFFFF;
            margin-bottom: 20px;
        }
        .product-title {
            font-size: 32px;
            font-weight: 700;
            color: #FEAE38;
            margin: 0 0 10px;
        }
        .price {
            font-size: 24px;
            color: #FFFFFF;
        }
        footer {
            text-align: center;
            padding: 40px;
            background: #000000;
            color: #888;
        }
